  workspace_uuid: p.workspace_uuid, base_parent_folder_id: p.base_parent_folder_id, root_folder_name: p.root_folder_name,
  folder_operations: p.folder_operations, file_operations: p.file_operations,
  total_operations: p.total_operations, created_at: p.created_at,
